.is-header header{padding-top:9px}.is-header .orientation{line-height:14px;margin:2px 0 4px!important}.is-header .pin-caption{margin-top:5px;font-size:10px;line-height:14px;min-height:14px}.is-header .part-body{padding-bottom:8px}
</style>

